?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Публикации | CMS</title><style>body{font:16px system-ui;max-width:1100px;margin:40px auto;padding:0 20px}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #ddd;padding:12px 8px}button{padding:7px}</style></head><body><h1>История публикаций</h1><p><a href="publish.php">Новая публикация</a> · <a href="index.php">Проекты</a></p><table><thead><tr><th>ID</th><th>Дата</th><th>Пользователь</th><th>Статус</th><th>Файлов</th><th>Комментарий/ошибка</th><th></th></tr></thead><tbody><?php foreach ($publications as $publication): ?><tr><td>#<?= (int) $publication['id'] ?></td><td><?= e($publication['created_at']) ?></td><td><?= e($publication['email']) ?></td><td><?= e($publication['status']) ?></td><td><?php $manifest = json_decode((string) $publication['manifest'], true); echo is_array($manifest) ? count($manifest) : 0; ?></td><td><?= e($publication['error_message'] ?: $publication['comment']) ?></td><td><?php if ($publication['status'] === 'published'): ?><form method="post" action="publication-rollback.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="publication_id" value="<?= (int) $publication['id'] ?>"><button type="submit">Вернуть</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></body></html>
